import { useEffect, useState } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import { store } from '../../store';
import { saveSettings } from '../../api/client';
import Toggle from '../shared/Toggle';
import LockBadge from '../shared/LockBadge';

export default function Settings() {
	const settings             = useSelect( ( s ) => s( store ).getSettings(), [] );
	const isPro                = useSelect( ( s ) => s( store ).isPro(), [] );
	const { setSettings }      = useDispatch( store );
	const [ form, setForm ]    = useState( {} );
	const [ saved, setSaved ]  = useState( false );

	useEffect( () => setForm( settings || {} ), [ settings ] );

	const set = ( k, v ) => setForm( ( p ) => ( { ...p, [ k ]: v } ) );

	const handleSave = async () => {
		const r = await saveSettings( form );
		setSettings( r?.data || form );
		setSaved( true );
		setTimeout( () => setSaved( false ), 2500 );
	};

	return (
		<div>
			<div className="ca-section-header">
				<div>
					<h2>{ __( 'Settings', 'checkout-architect-pro' ) }</h2>
					<p className="ca-help-text">{ __( 'Configure global behaviour for Checkout Architect Pro. Changes take effect after saving.', 'checkout-architect-pro' ) }</p>
				</div>
				<button type="button" className="ca-btn ca-btn--primary" onClick={ handleSave }>
					{ saved ? __( '✓ Saved', 'checkout-architect-pro' ) : __( 'Save Settings', 'checkout-architect-pro' ) }
				</button>
			</div>

			{ /* General */ }
			<div className="ca-card">
				<h3 className="ca-card-title">{ __( 'General', 'checkout-architect-pro' ) }</h3>
				<div className="ca-settings-row">
					<Toggle
						checked={ !! form.enable_for_all_users }
						onChange={ () => set( 'enable_for_all_users', ! form.enable_for_all_users ) }
						label={ __( 'Enable for all users', 'checkout-architect-pro' ) }
					/>
					<p className="ca-setting-desc">{ __( 'Show custom fields to all visitors including guests.', 'checkout-architect-pro' ) }</p>
				</div>
				<div className="ca-settings-row">
					<Toggle
						checked={ !! form.show_on_thankyou_page }
						onChange={ () => set( 'show_on_thankyou_page', ! form.show_on_thankyou_page ) }
						label={ __( 'Show fields on thank-you page', 'checkout-architect-pro' ) }
					/>
					<p className="ca-setting-desc">{ __( 'Display custom field values on the order confirmation page.', 'checkout-architect-pro' ) }</p>
				</div>
				<div className="ca-settings-row">
					<Toggle
						checked={ !! form.hide_billing_if_single }
						onChange={ () => set( 'hide_billing_if_single', ! form.hide_billing_if_single ) }
						label={ __( 'Hide customer type switcher when only 1 type exists', 'checkout-architect-pro' ) }
					/>
					<p className="ca-setting-desc">{ __( 'Automatically hides the type switcher if you only have one customer type configured.', 'checkout-architect-pro' ) }</p>
				</div>
			</div>

			{ /* Advanced */ }
			<div className="ca-card">
				<h3 className="ca-card-title">{ __( 'Advanced', 'checkout-architect-pro' ) }</h3>
				<div className="ca-settings-row">
					<Toggle
						checked={ !! form.log_field_errors }
						onChange={ () => set( 'log_field_errors', ! form.log_field_errors ) }
						label={ __( 'Log field validation errors', 'checkout-architect-pro' ) }
					/>
					<p className="ca-setting-desc">{ __( 'Write field validation errors to the WordPress debug log.', 'checkout-architect-pro' ) }</p>
				</div>
				<div className="ca-settings-row ca-settings-row--pro">
					<div className="ca-settings-row-label">
						<Toggle
							checked={ !! form.enable_preview_mode }
							disabled={ ! isPro }
							onChange={ () => set( 'enable_preview_mode', ! form.enable_preview_mode ) }
							label={ __( 'Enable live preview mode', 'checkout-architect-pro' ) }
						/>
						{ ! isPro && <LockBadge inline /> }
					</div>
					<p className="ca-setting-desc">{ __( 'Preview how your checkout fields look in real-time without going through checkout. (Pro feature)', 'checkout-architect-pro' ) }</p>
				</div>
			</div>

			{ /* Display */ }
			<div className="ca-card">
				<h3 className="ca-card-title">{ __( 'Display', 'checkout-architect-pro' ) }</h3>
				<div className="ca-field-group">
					<label>{ __( 'Currency position', 'checkout-architect-pro' ) }</label>
					<p className="ca-setting-desc">{ __( 'Where to show the currency symbol on custom price fields.', 'checkout-architect-pro' ) }</p>
					<select
						className="ca-select"
						style={ { maxWidth: '200px' } }
						value={ form.currency_position || 'before' }
						onChange={ ( e ) => set( 'currency_position', e.target.value ) }
					>
						<option value="before">{ __( 'Before amount', 'checkout-architect-pro' ) }</option>
						<option value="after">{ __( 'After amount', 'checkout-architect-pro' ) }</option>
					</select>
				</div>
				<div className="ca-field-group" style={ { marginTop: '16px' } }>
					<label>{ __( 'Date field format', 'checkout-architect-pro' ) }</label>
					<p className="ca-setting-desc">{ __( 'Format for date input fields, e.g. Y-m-d or d/m/Y.', 'checkout-architect-pro' ) }</p>
					<input
						className="ca-input"
						style={ { maxWidth: '200px' } }
						value={ form.date_format || '' }
						placeholder="Y-m-d"
						onChange={ ( e ) => set( 'date_format', e.target.value ) }
					/>
				</div>
			</div>

			{ /* Custom CSS */ }
			<div className="ca-card">
				<h3 className="ca-card-title">{ __( 'Custom CSS', 'checkout-architect-pro' ) }</h3>
				<p className="ca-setting-desc">{ __( 'Add custom CSS that will be loaded on the checkout page alongside your custom fields.', 'checkout-architect-pro' ) }</p>
				<textarea
					className="ca-input ca-textarea"
					rows="6"
					value={ form.custom_css || '' }
					placeholder="/* your custom styles */"
					onChange={ ( e ) => set( 'custom_css', e.target.value ) }
				/>
			</div>
		</div>
	);
}
