import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { useDispatch, useSelect } from '@wordpress/data';
import { store } from '../../store';
import { deleteField, updateField } from '../../api/client';

export default function FieldCard( { field } ) {
	const { attributes, listeners, setNodeRef, transform, transition } = useSortable( { id: field.id } );
	const style = { transform: CSS.Transform.toString( transform ), transition };
	const fields = useSelect( ( s ) => s( store ).getFields(), [] );
	const { setFields, setEditingFieldId } = useDispatch( store );
	return (
		<div ref={setNodeRef} style={style} className="ca-card">
			<span className="ca-drag-handle" {...attributes} {...listeners}>⠿</span>
			<span className="ca-badge">{ field.type }</span>
			<div>{ field.label }</div>
			<button type="button" className="ca-btn ca-btn--secondary" onClick={ () => setEditingFieldId( field.id ) }>Edit</button>
			<button type="button" className="ca-btn ca-btn--danger" onClick={ async () => { await deleteField( field.id ); setFields( fields.filter( ( f ) => f.id !== field.id ) ); } }>Delete</button>
			<button type="button" className="ca-btn ca-btn--ghost" onClick={ async () => { const res = await updateField( field.id, { enabled: ! field.enabled } ); setFields( fields.map( ( f ) => ( f.id === field.id ? ( res?.data || { ...field, enabled: ! field.enabled } ) : f ) ) ); } }>{ field.enabled ? 'Disable' : 'Enable' }</button>
		</div>
	);
}
