import { useState } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import { store } from '../../store';
import { createSection } from '../../api/client';
import SectionCard from './SectionCard';

export default function Sections() {
	const sections = useSelect( ( s ) => s( store ).getSections(), [] );
	const { setSections } = useDispatch( store );

	const [ showModal, setShowModal ] = useState( false );
	const [ form, setForm ]           = useState( { section_key: '', title: '', position: 'after_billing' } );
	const [ busy, setBusy ]           = useState( false );
	const [ error, setError ]         = useState( '' );

	const handleAdd = async () => {
		if ( ! form.section_key.trim() || ! form.title.trim() ) {
			setError( __( 'Section key and title are required.', 'checkout-architect-pro' ) );
			return;
		}
		setBusy( true ); setError( '' );
		try {
			const r = await createSection( form );
			setSections( [ ...sections, r?.data ] );
			setShowModal( false );
			setForm( { section_key: '', title: '', position: 'after_billing' } );
		} catch {
			setError( __( 'Could not create section. Please try again.', 'checkout-architect-pro' ) );
		} finally {
			setBusy( false );
		}
	};

	return (
		<div>
			<div className="ca-section-header">
				<div>
					<h2>{ __( 'Sections', 'checkout-architect-pro' ) }</h2>
					<p className="ca-help-text">{ __( 'Sections let you group custom fields under a heading on the checkout page — for example "Company Details" or "Delivery Preferences". Click', 'checkout-architect-pro' ) } <strong>{ __( 'Add Section', 'checkout-architect-pro' ) }</strong> { __( 'to create a new section, then assign fields to it in the Field Builder.', 'checkout-architect-pro' ) }</p>
				</div>
				<button
					type="button"
					className="ca-btn ca-btn--primary"
					onClick={ () => { setShowModal( true ); setError( '' ); } }
				>
					{ __( '+ Add Section', 'checkout-architect-pro' ) }
				</button>
			</div>

			{ sections.length === 0 && (
				<div className="ca-empty-state">
					<p>{ __( 'No sections yet. Click', 'checkout-architect-pro' ) } <strong>{ __( '+ Add Section', 'checkout-architect-pro' ) }</strong> { __( 'above to create your first section.', 'checkout-architect-pro' ) }</p>
				</div>
			) }

			{ sections.map( ( s ) => <SectionCard key={ s.id } section={ s } /> ) }

			{ showModal && (
				<div className="ca-modal-overlay" onClick={ ( e ) => e.target === e.currentTarget && setShowModal( false ) }>
					<div className="ca-modal">
						<div className="ca-modal__header">
							<h3>{ __( 'Add Section', 'checkout-architect-pro' ) }</h3>
							<button className="ca-modal__close" type="button" onClick={ () => setShowModal( false ) }>✕</button>
						</div>
						<div className="ca-modal__body">
							{ error && <div className="ca-alert ca-alert--error">{ error }</div> }
							<div className="ca-field-group">
								<label>{ __( 'Section Key', 'checkout-architect-pro' ) } <span className="ca-muted-label">{ __( '(unique identifier, e.g. "company_details")', 'checkout-architect-pro' ) }</span></label>
								<input
									className="ca-input"
									value={ form.section_key }
									onChange={ ( e ) => setForm( { ...form, section_key: e.target.value.toLowerCase().replace( /[^a-z0-9_]/g, '_' ) } ) }
									placeholder="e.g. company_details"
									autoFocus
								/>
							</div>
							<div className="ca-field-group">
								<label>{ __( 'Title', 'checkout-architect-pro' ) } <span className="ca-muted-label">{ __( '(heading shown on checkout)', 'checkout-architect-pro' ) }</span></label>
								<input
									className="ca-input"
									value={ form.title }
									onChange={ ( e ) => setForm( { ...form, title: e.target.value } ) }
									placeholder="e.g. Company Details"
								/>
							</div>
							<div className="ca-field-group">
								<label>{ __( 'Position', 'checkout-architect-pro' ) }</label>
								<select
									className="ca-select"
									value={ form.position }
									onChange={ ( e ) => setForm( { ...form, position: e.target.value } ) }
								>
									<option value="before_billing">{ __( 'Before billing fields', 'checkout-architect-pro' ) }</option>
									<option value="after_billing">{ __( 'After billing fields', 'checkout-architect-pro' ) }</option>
									<option value="before_order_notes">{ __( 'Before order notes', 'checkout-architect-pro' ) }</option>
									<option value="after_order_notes">{ __( 'After order notes', 'checkout-architect-pro' ) }</option>
								</select>
							</div>
						</div>
						<div className="ca-modal__footer">
							<button type="button" className="ca-btn" onClick={ () => setShowModal( false ) }>{ __( 'Cancel', 'checkout-architect-pro' ) }</button>
							<button type="button" className="ca-btn ca-btn--primary" onClick={ handleAdd } disabled={ busy }>
								{ busy ? __( 'Adding…', 'checkout-architect-pro' ) : __( 'Add Section', 'checkout-architect-pro' ) }
							</button>
						</div>
					</div>
				</div>
			) }
		</div>
	);
}
