import { useEffect, useState } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import { store } from '../../store';
import { createField, updateField } from '../../api/client';

const FIELD_TYPES = [
	{ value: 'text',     label: 'Text' },
	{ value: 'textarea', label: 'Textarea' },
	{ value: 'select',   label: 'Select (dropdown)' },
	{ value: 'radio',    label: 'Radio buttons' },
	{ value: 'checkbox', label: 'Checkbox' },
	{ value: 'number',   label: 'Number' },
	{ value: 'email',    label: 'Email' },
	{ value: 'phone',    label: 'Phone' },
	{ value: 'date',     label: 'Date picker' },
	{ value: 'file',     label: 'File upload' },
	{ value: 'hidden',   label: 'Hidden' },
	{ value: 'heading',  label: 'Heading / Divider' },
	{ value: 'custom_price', label: 'Custom price (adds fee)' },
];

const WIDTHS    = [ 'full', '1/2', '1/3', '2/3' ];
const POSITIONS = [ 'after_address', 'before_address', 'after_order_notes', 'before_order_notes' ];

const blank = {
	label: '', field_key: '', type: 'text', placeholder: '', description: '',
	required: false, width: 'full', position: 'after_address',
	conditions: { logic: 'AND', groups: [] }, pricing_rules: [],
};

export default function FieldEditor() {
	const editingFieldId         = useSelect( ( s ) => s( store ).getEditingFieldId(), [] );
	const fields                 = useSelect( ( s ) => s( store ).getFields(), [] );
	const { setEditingFieldId, setFields } = useDispatch( store );

	const current                = editingFieldId === 'new' ? null : fields.find( ( f ) => String( f.id ) === String( editingFieldId ) );
	const [ local, setLocal ]    = useState( blank );
	const [ touched, setTouched ] = useState( false );
	const [ busy, setBusy ]      = useState( false );

	useEffect( () => {
		setLocal( current ? { ...blank, ...current } : blank );
		setTouched( false );
	}, [ current ] );

	const set = ( k, v ) => setLocal( ( p ) => ( { ...p, [ k ]: v } ) );

	const handleSave = async () => {
		setBusy( true );
		try {
			const res = editingFieldId === 'new'
				? await createField( local )
				: await updateField( editingFieldId, local );
			const payload = res?.data || local;
			if ( editingFieldId === 'new' ) setFields( [ ...fields, payload ] );
			else setFields( fields.map( ( f ) => ( String( f.id ) === String( editingFieldId ) ? payload : f ) ) );
			setEditingFieldId( null );
		} finally {
			setBusy( false );
		}
	};

	return (
		<div className="ca-editor-panel">
			<h3 className="ca-editor-title">
				{ editingFieldId === 'new' ? __( 'Add New Field', 'checkout-architect-pro' ) : __( 'Edit Field', 'checkout-architect-pro' ) }
			</h3>

			{ /* Row 1: Label + Field Key */ }
			<div className="ca-card-grid">
				<div className="ca-field-group">
					<label>{ __( 'Field Label', 'checkout-architect-pro' ) } <span className="ca-required">*</span></label>
					<input
						className="ca-input"
						value={ local.label }
						placeholder={ __( 'e.g. Company Name', 'checkout-architect-pro' ) }
						onChange={ ( e ) => {
							const label = e.target.value;
							const next  = { ...local, label };
							if ( editingFieldId === 'new' && ! touched ) {
								next.field_key = label.toLowerCase().replace( /[^a-z0-9]+/g, '_' ).replace( /^_|_$/g, '' );
							}
							setLocal( next );
						} }
					/>
				</div>
				<div className="ca-field-group">
					<label>{ __( 'Field Key', 'checkout-architect-pro' ) } <span className="ca-muted-label">{ __( '(unique, no spaces)', 'checkout-architect-pro' ) }</span></label>
					<input
						className="ca-input"
						value={ local.field_key }
						placeholder="e.g. company_name"
						onChange={ ( e ) => { setTouched( true ); set( 'field_key', e.target.value ); } }
					/>
				</div>
			</div>

			{ /* Row 2: Type + Width */ }
			<div className="ca-card-grid">
				<div className="ca-field-group">
					<label>{ __( 'Field Type', 'checkout-architect-pro' ) }</label>
					<select className="ca-select" value={ local.type } onChange={ ( e ) => set( 'type', e.target.value ) }>
						{ FIELD_TYPES.map( ( ft ) => <option key={ ft.value } value={ ft.value }>{ ft.label }</option> ) }
					</select>
				</div>
				<div className="ca-field-group">
					<label>{ __( 'Width', 'checkout-architect-pro' ) }</label>
					<select className="ca-select" value={ local.width } onChange={ ( e ) => set( 'width', e.target.value ) }>
						{ WIDTHS.map( ( w ) => <option key={ w } value={ w }>{ w }</option> ) }
					</select>
				</div>
			</div>

			{ /* Row 3: Placeholder + Position */ }
			<div className="ca-card-grid">
				<div className="ca-field-group">
					<label>{ __( 'Placeholder', 'checkout-architect-pro' ) }</label>
					<input className="ca-input" value={ local.placeholder || '' } placeholder={ __( 'Optional hint text inside the field', 'checkout-architect-pro' ) } onChange={ ( e ) => set( 'placeholder', e.target.value ) } />
				</div>
				<div className="ca-field-group">
					<label>{ __( 'Position on checkout', 'checkout-architect-pro' ) }</label>
					<select className="ca-select" value={ local.position } onChange={ ( e ) => set( 'position', e.target.value ) }>
						{ POSITIONS.map( ( p ) => <option key={ p } value={ p }>{ p.replace( /_/g, ' ' ) }</option> ) }
					</select>
				</div>
			</div>

			{ /* Description */ }
			<div className="ca-field-group">
				<label>{ __( 'Description / Help text', 'checkout-architect-pro' ) }</label>
				<input className="ca-input" value={ local.description || '' } placeholder={ __( 'Shown below the field on checkout (optional)', 'checkout-architect-pro' ) } onChange={ ( e ) => set( 'description', e.target.value ) } />
			</div>

			{ /* Required toggle */ }
			<div className="ca-field-group ca-field-group--inline">
				<label>
					<input type="checkbox" checked={ !! local.required } onChange={ () => set( 'required', ! local.required ) } />
					{ ' ' }{ __( 'Required field', 'checkout-architect-pro' ) }
				</label>
			</div>

			{ /* Actions */ }
			<div className="ca-editor-actions">
				<button type="button" className="ca-btn ca-btn--primary" onClick={ handleSave } disabled={ busy }>
					{ busy ? __( 'Saving…', 'checkout-architect-pro' ) : __( 'Save Field', 'checkout-architect-pro' ) }
				</button>
				<button type="button" className="ca-btn" onClick={ () => setEditingFieldId( null ) }>
					{ __( 'Cancel', 'checkout-architect-pro' ) }
				</button>
			</div>
		</div>
	);
}
