import { useState } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import { store } from '../../store';
import { deleteType, updateType } from '../../api/client';

export default function TypeCard( { type } ) {
	const [ local, setLocal ]   = useState( type );
	const [ saved, setSaved ]   = useState( false );
	const types                  = useSelect( ( s ) => s( store ).getTypes(), [] );
	const { setTypes }           = useDispatch( store );

	const handleSave = async () => {
		const r = await updateType( type.id, local );
		setTypes( types.map( ( t ) => ( t.id === type.id ? ( r?.data || local ) : t ) ) );
		setSaved( true );
		setTimeout( () => setSaved( false ), 2000 );
	};

	const handleDelete = async () => {
		if ( ! window.confirm( __( 'Delete this customer type? This cannot be undone.', 'checkout-architect-pro' ) ) ) return;
		await deleteType( type.id );
		setTypes( types.filter( ( t ) => t.id !== type.id ) );
	};

	return (
		<div className="ca-card">
			<div className="ca-card-grid">
				<div className="ca-field-group">
					<label>{ __( 'Slug', 'checkout-architect-pro' ) }</label>
					<input
						className="ca-input"
						value={ local.slug }
						onChange={ ( e ) => setLocal( { ...local, slug: e.target.value } ) }
						placeholder="e.g. wholesale"
					/>
				</div>
				<div className="ca-field-group">
					<label>{ __( 'Label', 'checkout-architect-pro' ) }</label>
					<input
						className="ca-input"
						value={ local.label }
						onChange={ ( e ) => setLocal( { ...local, label: e.target.value } ) }
						placeholder="e.g. Wholesale Customer"
					/>
				</div>
			</div>
			<div className="ca-card-actions">
				<button type="button" className="ca-btn ca-btn--primary ca-btn--sm" onClick={ handleSave }>
					{ saved ? __( '✓ Saved', 'checkout-architect-pro' ) : __( 'Save', 'checkout-architect-pro' ) }
				</button>
				<button type="button" className="ca-btn ca-btn--danger ca-btn--sm" onClick={ handleDelete }>
					{ __( 'Delete', 'checkout-architect-pro' ) }
				</button>
			</div>
		</div>
	);
}
