	return <div className="ca-lock-badge ca-lock-badge--overlay"><span className="dashicons dashicons-lock" /><p>{ message ?? __( 'This is a Pro feature. Upgrade to unlock.', 'checkout-architect-pro' ) }</p><a href="https://coderembassy.com/checkout-architect-pro" className="ca-btn ca-btn--primary" target="_blank" rel="noopener">{ __( 'Upgrade to Pro', 'checkout-architect-pro' ) }</a></div>;
