import { useEffect, useState } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { activateLicense, deactivateLicense, getLicenseStatus } from '../../api/client';

export default function License() {
	const [ info, setInfo ]   = useState( { status: 'inactive', key: '' } );
	const [ key, setKey ]     = useState( '' );
	const [ busy, setBusy ]   = useState( false );
	const [ error, setError ] = useState( '' );

	useEffect( () => {
		getLicenseStatus().then( ( r ) => setInfo( r?.data || r || {} ) );
	}, [] );

	const masked = info?.key ? `••••••••••••${ String( info.key ).slice( -4 ) }` : '';
	const isActive = info?.status === 'active';

	const handleActivate = async () => {
		if ( ! key.trim() ) { setError( __( 'Please enter a license key.', 'checkout-architect-pro' ) ); return; }
		setBusy( true ); setError( '' );
		try {
			await activateLicense( key );
			const r = await getLicenseStatus();
			setInfo( r?.data || r || {} );
			setKey( '' );
		} catch ( e ) {
			setError( __( 'Activation failed. Please check your license key.', 'checkout-architect-pro' ) );
		} finally {
			setBusy( false );
		}
	};

	const handleDeactivate = async () => {
		if ( ! window.confirm( __( 'Deactivate this license?', 'checkout-architect-pro' ) ) ) return;
		setBusy( true );
		try {
			await deactivateLicense();
			const r = await getLicenseStatus();
			setInfo( r?.data || r || {} );
		} finally {
			setBusy( false );
		}
	};

	return (
		<div className="ca-license-box">
			<h2>{ __( 'License Activation', 'checkout-architect-pro' ) }</h2>
			<p>{ __( 'Enter your license key to unlock Pro features. Purchase at', 'checkout-architect-pro' ) }{ ' ' }
				<a href="https://coderembassy.com/checkout-architect-pro" target="_blank" rel="noopener noreferrer">coderembassy.com</a>.
			</p>

			{ error && <div className="ca-alert ca-alert--error">{ error }</div> }

			{ ! isActive ? (
				<div className="ca-form-row">
					<input
						className="ca-input"
						type="text"
						placeholder={ __( 'xxxx-xxxx-xxxx-xxxx', 'checkout-architect-pro' ) }
						value={ key }
						onChange={ ( e ) => setKey( e.target.value ) }
						disabled={ busy }
					/>
					<button
						className="ca-btn ca-btn--primary"
						type="button"
						onClick={ handleActivate }
						disabled={ busy }
					>
						{ busy ? __( 'Activating…', 'checkout-architect-pro' ) : __( 'Activate', 'checkout-architect-pro' ) }
					</button>
				</div>
			) : (
				<div className="ca-form-row">
					<input className="ca-input" type="text" value={ masked } readOnly />
					<span className="ca-badge">{ __( 'Active', 'checkout-architect-pro' ) }</span>
					<button
						className="ca-btn ca-btn--danger"
						type="button"
						onClick={ handleDeactivate }
						disabled={ busy }
					>
						{ busy ? __( 'Deactivating…', 'checkout-architect-pro' ) : __( 'Deactivate', 'checkout-architect-pro' ) }
					</button>
				</div>
			) }
		</div>
	);
}
