import apiFetch from '@wordpress/api-fetch';
const BASE = window.CA?.rest_url ?? '';
apiFetch.use( apiFetch.createNonceMiddleware( window.CA?.nonce ?? '' ) );
export const getFields = () => apiFetch( { url: BASE + 'fields' } );
export const createField = ( data ) => apiFetch( { url: BASE + 'fields', method: 'POST', data } );
export const updateField = ( id, data ) => apiFetch( { url: BASE + `fields/${ id }`, method: 'PUT', data } );
export const deleteField = ( id ) => apiFetch( { url: BASE + `fields/${ id }`, method: 'DELETE' } );
export const reorderFields = ( order ) => apiFetch( { url: BASE + 'fields/reorder', method: 'POST', data: { order } } );
export const getRevisions = ( id ) => apiFetch( { url: BASE + `fields/${ id }/revisions` } );
export const rollbackRevision = ( id, revId ) => apiFetch( { url: BASE + `fields/${ id }/revisions/${ revId }/rollback`, method: 'POST' } );
export const getTypes = () => apiFetch( { url: BASE + 'customer-types' } );
export const createType = ( data ) => apiFetch( { url: BASE + 'customer-types', method: 'POST', data } );
export const updateType = ( id, data ) => apiFetch( { url: BASE + `customer-types/${ id }`, method: 'PUT', data } );
export const deleteType = ( id ) => apiFetch( { url: BASE + `customer-types/${ id }`, method: 'DELETE' } );
export const getSections = () => apiFetch( { url: BASE + 'sections' } );
export const createSection = ( data ) => apiFetch( { url: BASE + 'sections', method: 'POST', data } );
export const updateSection = ( id, data ) => apiFetch( { url: BASE + `sections/${ id }`, method: 'PUT', data } );
export const deleteSection = ( id ) => apiFetch( { url: BASE + `sections/${ id }`, method: 'DELETE' } );
export const getSettings = () => apiFetch( { url: BASE + 'settings' } );
export const saveSettings = ( data ) => apiFetch( { url: BASE + 'settings', method: 'POST', data } );
export const getTemplates = () => apiFetch( { url: BASE + 'templates' } );
export const saveTemplate = ( data ) => apiFetch( { url: BASE + 'templates', method: 'POST', data } );
export const applyTemplate = ( id ) => apiFetch( { url: BASE + `templates/${ id }/apply`, method: 'POST' } );
export const deleteTemplate = ( id ) => apiFetch( { url: BASE + `templates/${ id }`, method: 'DELETE' } );
export const previewField = ( data ) => apiFetch( { url: BASE + 'preview', method: 'POST', data } );
export const activateLicense = ( key ) => apiFetch( { url: BASE + 'license/activate', method: 'POST', data: { license_key: key } } );
export const deactivateLicense = () => apiFetch( { url: BASE + 'license/deactivate', method: 'POST' } );
export const getLicenseStatus = () => apiFetch( { url: BASE + 'license/status' } );
