import { useDispatch, useSelect } from '@wordpress/data';
import { store } from '../../store';
import { applyTemplate, getFields, saveTemplate } from '../../api/client';
import LockBadge from '../shared/LockBadge';
export default function Templates() {
	const isPro = useSelect( ( s ) => s( store ).isPro(), [] );
	const templates = useSelect( ( s ) => s( store ).getTemplates(), [] );
	const { setFields } = useDispatch( store );
	if ( ! isPro ) return <LockBadge message="Templates are a Pro feature" />;
	return <section><button type="button" className="ca-btn ca-btn--primary" onClick={ async () => { const name = window.prompt( 'name', '' ); if ( name ) await saveTemplate( { name } ); } }>Save Current as Template</button>{ templates.map( ( t ) => <div key={ t.id } className="ca-card"><strong>{ t.name }</strong><button type="button" className="ca-btn ca-btn--secondary" onClick={ async () => { if ( ! window.confirm( 'Apply template?' ) ) return; await applyTemplate( t.id ); const f = await getFields(); setFields( f?.data || [] ); } }>Apply</button></div> ) }</section>;
}
