import { useEffect } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { store } from '../store';
import { getFields, getTypes, getSections, getSettings, getTemplates } from '../api/client';
import Topbar from './Topbar';
import Sidebar from './Sidebar';
import FieldBuilder from './FieldBuilder';
import CustomerTypes from './CustomerTypes';
import Sections from './Sections';
import Templates from './Templates';
import Settings from './Settings';
import License from './License';
import ErrorBoundary from './shared/ErrorBoundary';

function Notice() {
	const notice = useSelect( ( s ) => s( store ).getNotice(), [] );
	const { setNotice } = useDispatch( store );
	useEffect( () => {
		if ( ! notice ) return;
		const timer = setTimeout( () => setNotice( null ), 4000 );
		return () => clearTimeout( timer );
	}, [ notice, setNotice ] );
	if ( ! notice ) return null;
	return <div className={ `ca-alert ca-alert--${ notice.type }` }>{ notice.message }</div>;
}

function Hero() {
	const globals = useSelect( ( s ) => s( store ).getGlobals(), [] );
	return (
		<div className="ca-hero-card">
			<div className="ca-hero-card__body">
				<h1 className="ca-hero-card__title">Checkout Architect Pro</h1>
				<p className="ca-hero-card__desc">Advanced WooCommerce checkout field manager with conditional logic, customer types &amp; pricing rules. Use the sidebar to navigate between sections.</p>
			</div>
			<span className="ca-hero-card__version">v{ globals?.version || '1.0.0' }</span>
		</div>
	);
}

export default function App() {
	const { setFields, setTypes, setSections, setSettings, setTemplates } = useDispatch( store );
	const activeTab = useSelect( ( s ) => s( store ).getActiveTab(), [] );
	const isDark    = useSelect( ( s ) => s( store ).isDark(), [] );

	useEffect( () => {
		Promise.allSettled( [
			getFields(),
			getTypes(),
			getSections(),
			getSettings(),
			getTemplates(),
		] ).then( ( [ a, b, c, d, e ] ) => {
			if ( a.status === 'fulfilled' ) setFields( a.value?.data || [] );
			if ( b.status === 'fulfilled' ) setTypes( b.value?.data || [] );
			if ( c.status === 'fulfilled' ) setSections( c.value?.data || [] );
			if ( d.status === 'fulfilled' ) setSettings( d.value?.data || {} );
			if ( e.status === 'fulfilled' ) setTemplates( e.value?.data || [] );
		} );
	}, [ setFields, setTypes, setSections, setSettings, setTemplates ] );

	return (
		<div id="ca-root" data-theme={ isDark ? 'dark' : 'light' }>
			<Topbar />
			<div className="ca-layout">
				<Sidebar />
				<main className="ca-content">
					<Notice />
					<Hero />
					{ activeTab === 'fields'    && <ErrorBoundary key="fields"><FieldBuilder /></ErrorBoundary> }
					{ activeTab === 'types'     && <ErrorBoundary key="types"><CustomerTypes /></ErrorBoundary> }
					{ activeTab === 'sections'  && <ErrorBoundary key="sections"><Sections /></ErrorBoundary> }
					{ activeTab === 'templates' && <ErrorBoundary key="templates"><Templates /></ErrorBoundary> }
					{ activeTab === 'settings'  && <ErrorBoundary key="settings"><Settings /></ErrorBoundary> }
					{ activeTab === 'license'   && <ErrorBoundary key="license"><License /></ErrorBoundary> }
				</main>
			</div>
		</div>
	);
}
