import { useState } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import { store } from '../../store';
import { createType } from '../../api/client';
import TypeCard from './TypeCard';
import LockBadge from '../shared/LockBadge';

export default function CustomerTypes() {
	const types  = useSelect( ( s ) => s( store ).getTypes(), [] );
	const isPro  = useSelect( ( s ) => s( store ).isPro(), [] );
	const { setTypes } = useDispatch( store );

	const [ showModal, setShowModal ] = useState( false );
	const [ form, setForm ]           = useState( { slug: '', label: '' } );
	const [ busy, setBusy ]           = useState( false );
	const [ error, setError ]         = useState( '' );

	const canAdd = isPro || types.length < 2;

	const handleAdd = async () => {
		if ( ! form.slug.trim() || ! form.label.trim() ) {
			setError( __( 'Both slug and label are required.', 'checkout-architect-pro' ) );
			return;
		}
		setBusy( true ); setError( '' );
		try {
			const res = await createType( form );
			setTypes( [ ...types, res?.data ] );
			setShowModal( false );
			setForm( { slug: '', label: '' } );
		} catch {
			setError( __( 'Could not create type. Please try again.', 'checkout-architect-pro' ) );
		} finally {
			setBusy( false );
		}
	};

	return (
		<div>
			<div className="ca-section-header">
				<div>
					<h2>{ __( 'Customer Types', 'checkout-architect-pro' ) }</h2>
					<p className="ca-help-text">{ __( 'Customer types let you show or hide fields based on who is shopping — e.g. Retail, Wholesale, B2B. Each type can have its own set of checkout fields. Click a type below to edit it, or click', 'checkout-architect-pro' ) } <strong>{ __( 'Add Type', 'checkout-architect-pro' ) }</strong> { __( 'to create a new one.', 'checkout-architect-pro' ) }</p>
				</div>
				<button
					type="button"
					className="ca-btn ca-btn--primary"
					disabled={ ! canAdd }
					onClick={ () => { setShowModal( true ); setError( '' ); } }
				>
					{ __( '+ Add Type', 'checkout-architect-pro' ) }
				</button>
			</div>

			{ ! isPro && types.length >= 2 && (
				<div className="ca-alert ca-alert--error">
					{ __( 'Free plan supports up to 2 customer types.', 'checkout-architect-pro' ) } <a href="https://coderembassy.com/checkout-architect-pro" target="_blank" rel="noopener noreferrer">{ __( 'Upgrade to Pro', 'checkout-architect-pro' ) }</a> { __( 'for unlimited types.', 'checkout-architect-pro' ) }
				</div>
			) }

			{ types.length === 0 && (
				<div className="ca-empty-state">
					<p>{ __( 'No customer types yet. Click', 'checkout-architect-pro' ) } <strong>{ __( '+ Add Type', 'checkout-architect-pro' ) }</strong> { __( 'above to create your first type.', 'checkout-architect-pro' ) }</p>
				</div>
			) }

			{ types.map( ( t ) => <TypeCard key={ t.id } type={ t } /> ) }

			{ showModal && (
				<div className="ca-modal-overlay" onClick={ ( e ) => e.target === e.currentTarget && setShowModal( false ) }>
					<div className="ca-modal">
						<div className="ca-modal__header">
							<h3>{ __( 'Add Customer Type', 'checkout-architect-pro' ) }</h3>
							<button className="ca-modal__close" type="button" onClick={ () => setShowModal( false ) }>✕</button>
						</div>
						<div className="ca-modal__body">
							{ error && <div className="ca-alert ca-alert--error">{ error }</div> }
							<div className="ca-field-group">
								<label>{ __( 'Slug', 'checkout-architect-pro' ) } <span className="ca-muted-label">{ __( '(unique key, e.g. "wholesale")', 'checkout-architect-pro' ) }</span></label>
								<input
									className="ca-input"
									value={ form.slug }
									onChange={ ( e ) => setForm( { ...form, slug: e.target.value.toLowerCase().replace( /[^a-z0-9_]/g, '_' ) } ) }
									placeholder="e.g. wholesale"
									autoFocus
								/>
							</div>
							<div className="ca-field-group">
								<label>{ __( 'Label', 'checkout-architect-pro' ) } <span className="ca-muted-label">{ __( '(display name, e.g. "Wholesale Customer")', 'checkout-architect-pro' ) }</span></label>
								<input
									className="ca-input"
									value={ form.label }
									onChange={ ( e ) => setForm( { ...form, label: e.target.value } ) }
									placeholder="e.g. Wholesale Customer"
								/>
							</div>
						</div>
						<div className="ca-modal__footer">
							<button type="button" className="ca-btn" onClick={ () => setShowModal( false ) }>{ __( 'Cancel', 'checkout-architect-pro' ) }</button>
							<button type="button" className="ca-btn ca-btn--primary" onClick={ handleAdd } disabled={ busy }>
								{ busy ? __( 'Adding…', 'checkout-architect-pro' ) : __( 'Add Type', 'checkout-architect-pro' ) }
							</button>
						</div>
					</div>
				</div>
			) }
		</div>
	);
}
